function getYearList(yearsBefore = 4, yearsAfter = 1) {
    const currentYear = new Date().getFullYear();
    const years = [];

    for (let i = currentYear - yearsBefore; i <= currentYear + yearsAfter; i++) {
        years.push(i);
    }

    return years;
}

